values ('ap_physics_c_em', 10, '10.1', array['10.1', '10.2']::text[], 'list_sequence', 'Conductor in electrostatic equilibrium: required properties', 'Properties a student must state or apply for a conductor in electrostatic equilibrium.', '[{"label": "Excess charge on the surface", "meaning": "Mutual repulsion puts all excess charge carriers on the conductor''s surface; the interior has no net charge."}, {"label": "Zero field inside", "meaning": "The electric field is zero within the conductor."}, {"label": "Field perpendicular to the surface", "meaning": "The electric field is perpendicular to the outer surface of the conductor."}, {"label": "Equipotential", "meaning": "All points on the surface have the same electric potential, so the conductor is an equipotential surface."}, {"label": "Greater charge density at points and edges", "meaning": "Surface charge density is greater at points or edges than on planar areas."}, {"label": "Negligible equilibrium time", "meaning": "The time for charges to reach equilibrium is so short as to be negligible."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-em-reference-u8-u10-2026-10-10; candidate=ap_physics_c_em-u10-r1-002; ced=10.1.A.2, 10.1.A.3.i-iii, 10.1.A.4, 10.1.A.5 "charge carriers residing entirely on the surface"')
